package com.google.javascript.rhino;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TokenStream_isJSIdentifier_TriageGen1Test {



    @Test
    public void testIsJSIdentifier_InvalidStartChar() {
        // Starts with a digit
        assertFalse(TokenStream.isJSIdentifier("1abc"));
        // Starts with a symbol
        assertFalse(TokenStream.isJSIdentifier("_!abc"));
        // Starts with a space
        assertFalse(TokenStream.isJSIdentifier(" abc"));
    }








}

