package com.google.javascript.rhino;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TokenStream_isJSIdentifier_TriageGen1Test {







    @Test
    public void testIsJSIdentifier_ValidMultiChar() {
        assertTrue(TokenStream.isJSIdentifier("abc"));
        assertTrue(TokenStream.isJSIdentifier("abc123"));
        assertTrue(TokenStream.isJSIdentifier("_varName"));
        assertTrue(TokenStream.isJSIdentifier("$price"));
    }




}

package com.google.javascript.rhino;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TokenStream_isJSIdentifier_TriageGen1Test {









    @Test
    public void testIsJSIdentifier_InvalidPartChar() {
        // Valid start, but invalid middle character (hyphen)
        assertFalse(TokenStream.isJSIdentifier("a-b"));
        // Valid start, but invalid middle character (space)
        assertFalse(TokenStream.isJSIdentifier("a b"));
        // Valid start, but invalid middle character (dot)
        assertFalse(TokenStream.isJSIdentifier("a.b"));
    }


}

